using _29_PhamAnhTuan_Assignment01_FrontEnd.Models;
using _29_PhamAnhTuan_Assignment01_FrontEnd.Services;
using Microsoft.AspNetCore.Mvc;
namespace _29_PhamAnhTuan_Assignment01_FrontEnd.Controllers;
public sealed class ManagementController(BackendApiClient api) : Controller
{
    private bool Is(string role) => string.Equals(HttpContext.Session.GetString("UserRole"), role, StringComparison.OrdinalIgnoreCase);
    [HttpGet] public IActionResult Report() => Is("Admin") ? View() : Forbid();
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> Report(DateTime startDate, DateTime endDate, CancellationToken ct) { if (!Is("Admin")) return Forbid(); ViewBag.StartDate = startDate; ViewBag.EndDate = endDate; return View(await api.ReportAsync(startDate, endDate, ct)); }
    [HttpGet] public async Task<IActionResult> Accounts(string? search, CancellationToken ct) => Is("Admin") ? View(await api.AccountsAsync(search, ct)) : Forbid();
    [HttpGet] public IActionResult CreateAccount() => Is("Admin") ? View(new AccountFormModel()) : Forbid();
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> CreateAccount(AccountFormModel model, CancellationToken ct) { if (!Is("Admin")) return Forbid(); if (!await api.PostAsync("api/accounts", model, ct)) ModelState.AddModelError("", "Không thể tạo account."); return ModelState.IsValid ? RedirectToAction(nameof(Accounts)) : View(model); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> DeleteAccount(short id, CancellationToken ct) { if (!Is("Admin")) return Forbid(); await api.DeleteAsync($"api/accounts/{id}", ct); return RedirectToAction(nameof(Accounts)); }
    [HttpGet] public async Task<IActionResult> EditAccount(short id, CancellationToken ct) { if (!Is("Admin")) return Forbid(); var a = (await api.AccountsAsync(null, ct)).FirstOrDefault(x => x.AccountId == id); return a is null ? NotFound() : View(new AccountFormModel { AccountName = a.AccountName ?? "", AccountEmail = a.AccountEmail ?? "", AccountRole = a.AccountRole ?? 1 }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> EditAccount(short id, AccountFormModel model, CancellationToken ct) { if (!Is("Admin")) return Forbid(); if (!await api.PutAsync($"api/accounts/{id}", model, ct)) ModelState.AddModelError("", "Không thể cập nhật account."); return ModelState.IsValid ? RedirectToAction(nameof(Accounts)) : View(model); }
    [HttpGet] public async Task<IActionResult> Categories(string? search, CancellationToken ct) => Is("Staff") ? View(await api.CategoriesAsync(search, ct)) : Forbid();
    [HttpGet] public IActionResult CreateCategory() => Is("Staff") ? View(new CategoryFormModel()) : Forbid();
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> CreateCategory(CategoryFormModel model, CancellationToken ct) { if (!Is("Staff")) return Forbid(); if (!await api.PostAsync("api/categories", model, ct)) ModelState.AddModelError("", "Không thể tạo category."); return ModelState.IsValid ? RedirectToAction(nameof(Categories)) : View(model); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> DeleteCategory(short id, CancellationToken ct) { if (!Is("Staff")) return Forbid(); await api.DeleteAsync($"api/categories/{id}", ct); return RedirectToAction(nameof(Categories)); }
    [HttpGet] public async Task<IActionResult> EditCategory(short id, CancellationToken ct) { if (!Is("Staff")) return Forbid(); var c = (await api.CategoriesAsync(null, ct)).FirstOrDefault(x => x.CategoryId == id); return c is null ? NotFound() : View(new CategoryFormModel { CategoryName = c.CategoryName, CategoryDesciption = c.CategoryDesciption, IsActive = c.IsActive ?? false }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> EditCategory(short id, CategoryFormModel model, CancellationToken ct) { if (!Is("Staff")) return Forbid(); if (!await api.PutAsync($"api/categories/{id}", model, ct)) ModelState.AddModelError("", "Không thể cập nhật category."); return ModelState.IsValid ? RedirectToAction(nameof(Categories)) : View(model); }
    [HttpGet] public async Task<IActionResult> News(string? search, CancellationToken ct) => Is("Staff") ? View(await api.NewsAsync(search, ct)) : Forbid();
    [HttpGet] public IActionResult CreateNews() => Is("Staff") ? View(new NewsFormModel()) : Forbid();
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> CreateNews(NewsFormModel model, CancellationToken ct) { if (!Is("Staff")) return Forbid(); if (!await api.PostAsync("api/news-articles", model, ct)) ModelState.AddModelError("", "Không thể tạo news article."); return ModelState.IsValid ? RedirectToAction(nameof(News)) : View(model); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> DeleteNews(string id, CancellationToken ct) { if (!Is("Staff")) return Forbid(); await api.DeleteAsync($"api/news-articles/{id}", ct); return RedirectToAction(nameof(News)); }
    [HttpGet] public async Task<IActionResult> EditNews(string id, CancellationToken ct) { if (!Is("Staff")) return Forbid(); var n = (await api.NewsAsync(null, ct)).FirstOrDefault(x => x.NewsArticleId == id); return n is null ? NotFound() : View(new NewsFormModel { NewsArticleId = n.NewsArticleId, NewsTitle = n.NewsTitle, Headline = n.Headline, NewsContent = n.NewsContent ?? "", NewsSource = n.NewsSource, CategoryId = n.CategoryId, NewsStatus = n.NewsStatus ?? false }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> EditNews(string id, NewsFormModel model, CancellationToken ct) { if (!Is("Staff")) return Forbid(); if (!await api.PutAsync($"api/news-articles/{id}", model, ct)) ModelState.AddModelError("", "Không thể cập nhật news."); return ModelState.IsValid ? RedirectToAction(nameof(News)) : View(model); }
    [HttpGet] public async Task<IActionResult> Tags(string? search, CancellationToken ct) => Is("Staff") ? View(await api.TagsAsync(search, ct)) : Forbid();
    [HttpGet] public IActionResult CreateTag() => Is("Staff") ? View(new TagFormModel()) : Forbid();
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> CreateTag(TagFormModel model, CancellationToken ct) { if (!Is("Staff")) return Forbid(); if (!await api.PostAsync("api/tags", model, ct)) ModelState.AddModelError("", "Không thể tạo tag."); return ModelState.IsValid ? RedirectToAction(nameof(Tags)) : View(model); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> DeleteTag(int id, CancellationToken ct) { if (!Is("Staff")) return Forbid(); await api.DeleteAsync($"api/tags/{id}", ct); return RedirectToAction(nameof(Tags)); }
}
